# ---- config ---------------------------------------------------------------
RESULTS = '/scratch/ni2071/Diffusion/Squidiff_git/Squidiff/results_base_corrected'
DATA_DIR = '/scratch/ni2071/Diffusion/tahoe/datasets_step15'   # Step 15 port: Tahoe test files
GENE_SIZE = 200
MAX_CELLS_PER_COND = 200
SAVE_PER_CELL = os.environ.get('SQUIDIFF_SAVE_PER_CELL', '0') == '1'
_PC = {'pred': [], 'true': [], 'cond': []}
SPLITS = ['drug_split_0', 'drug_split_1', 'drug_split_2',
          'random_split_0', 'random_split_1', 'random_split_2']

_VEC = {'cond': [], 'true': [], 'A': [], 'B': [], 'C': []}
def r2(a, b):
    ss_res = np.sum((a - b) ** 2); ss_tot = np.sum((a - a.mean()) ** 2)
    return 0.0 if ss_tot == 0 else 1 - ss_res / ss_tot

def dense(x): return x.toarray() if hasattr(x, 'toarray') else np.asarray(x)


MODEL_OVERRIDE = None
TAG = None


def run_split(split):
    model_path = MODEL_OVERRIDE if MODEL_OVERRIDE else os.path.join(RESULTS, f'base_{split}', 'model_0.9999.pt')
    print('  model: ' + model_path)
    # BASE sampler signature: (model_path, gene_size, output_dim, use_drug_structure)
    sampler = sample_squidiff.sampler(model_path, GENE_SIZE, GENE_SIZE, True)

    def decode(z):
        out = []
        for s in range(0, z.shape[0], 256):
            pb = sampler.pred(z[s:s+256], gene_size=GENE_SIZE)
            out.append(pb.detach().cpu().numpy())
        return np.concatenate(out, 0)

    treated = sc.read_h5ad(f'{DATA_DIR}/tahoe_test_{split}.h5ad')
    control = sc.read_h5ad(f'{DATA_DIR}/tahoe_test_{split}_control.h5ad')
    tX = dense(treated.X); cX = dense(control.X)

    # sci-Plex obs: Group (=cov_drug_dose_name), SMILES, dose, cell_name
    t_group = treated.obs['Group'].astype(str).values      # cellline_drug_dose
    t_smiles = treated.obs['SMILES'].astype(str).values
    t_dose = treated.obs['dose'].astype(float).values
    t_line = treated.obs['cell_name'].astype(str).values
    c_line = control.obs['cell_name'].astype(str).values
    # Step 15 port: the paired control is the vehicle population of the same line AND plate (PREREG_step15a 4.8).
    # Group ends with _p<plate> in both files (drug names carry no underscore), so the plate is its last field.
    def _plate(groups):
        p = np.array([g.rsplit('_p', 1)[1] for g in groups])
        if not all(x.isdigit() for x in p):
            raise SystemExit('FATAL: non-numeric plate suffix in Group')
        return p
    t_plate = _plate(t_group)
    c_plate = _plate(control.obs['Group'].astype(str).values)

    # per-line control pool (for Protocol B sampling and Protocol C mean)
    ctrl_pool = {(L, P): cX[(c_line == L) & (c_plate == P)]
                 for L in np.unique(c_line) for P in np.unique(c_plate[c_line == L])}   # Step 15 port: (line, plate)

    # condition = full cellline_drug_dose label (matches sci-Plex granularity)
    keys = t_group
    rA = {'all': [], 'degs': [], 'pearson_all': [], 'pearson_degs': []}
    rB = {'all': [], 'degs': [], 'pearson_all': [], 'pearson_degs': []}
    rC = {'all': [], 'degs': [], 'pearson_all': [], 'pearson_degs': []}
    per_line = {}

    for i_cond, cond in enumerate(np.unique(keys)):
        m = keys == cond
        if m.sum() <= 5:
            continue
        line = t_line[m][0]
        plate = t_plate[m][0]
        pool = ctrl_pool.get((line, plate))   # Step 15 port
        if pool is None or len(pool) == 0:
            continue

        real = tX[m]
        real_mean = real.mean(0)

        idx = np.arange(real.shape[0])
        if len(idx) > MAX_CELLS_PER_COND:
            idx = np.random.RandomState(0).choice(idx, MAX_CELLS_PER_COND, replace=False)
        real_sub = real[idx]
        n = real_sub.shape[0]

        # drug fingerprint for this condition (same drug/dose across the condition)
        smi = t_smiles[m][0]
        dose = float(np.median(t_dose[m]))
        fp = torch.tensor(Drug_dose_encoder([smi]*n, [dose]*n, comb_num=1),
                          dtype=torch.float32).to('cuda')

        # dummy x_start (IGNORED by the base encoder; only shape must be valid)
        dummy = torch.zeros((n, GENE_SIZE), dtype=torch.float32).to('cuda')

        # ---- Protocol A: control_feature = TREATED cells ----
        cfA = torch.tensor(real_sub, dtype=torch.float32).to('cuda')
        # Step 6 arm C, prereg amendment 11: each protocol integrates from what
        # it is conditioned on. Protocol A has no control cells, so it starts
        # from the treated cells. Inert for every other arm.
        setattr(sampler, '_fm_x0', cfA)
        with torch.no_grad():
            zA = sampler.model.encoder(dummy, None, fp, cfA)   # (x_start, label, drug_dose, control_feature)
        torch.manual_seed(i_cond); torch.cuda.manual_seed_all(i_cond)
        predA = decode(zA).mean(0)

        # ---- Protocol B: control_feature = CONTROL cells of same line ----
        cidx = np.random.RandomState(i_cond).choice(len(pool), n, replace=(len(pool) < n))
        cfB = torch.tensor(pool[cidx], dtype=torch.float32).to('cuda')
        # Step 6 arm C integrates its ODE from the SAME control cells the
        # encoder is conditioned on. Inert for every other arm and for Steps
        # 4, 4b and 5: the base sampler has no _fm_x0 attribute and never
        # reads it, so this line only ever sets an unused attribute.
        setattr(sampler, '_fm_x0', cfB)
        with torch.no_grad():
            zB = sampler.model.encoder(dummy, None, fp, cfB)
        torch.manual_seed(i_cond); torch.cuda.manual_seed_all(i_cond)
        _pcB = decode(zB)
        if SAVE_PER_CELL:
            # prereg amendment 12: retain the per-cell population for P2.
            # Storage only - no model call, no RNG draw, no selection change.
            _PC['pred'].append(np.asarray(_pcB, dtype=np.float32))
            _PC['true'].append(np.asarray(real_sub, dtype=np.float32))
            _PC['cond'].append(str(cond))
        predB = _pcB.mean(0)

        # ---- Protocol C: control mean (no model) ----
        predC = pool.mean(0)

        # DEGs: top-50 genes by |treated_mean - control_mean|  (same as Tahoe/GBM)
        degs = np.argsort(np.abs(real_mean - predC))[-50:]

        _VEC['cond'].append(str(cond)); _VEC['true'].append(np.asarray(real_mean, dtype=np.float32))
        _VEC['A'].append(np.asarray(predA, dtype=np.float32)); _VEC['B'].append(np.asarray(predB, dtype=np.float32))
        _VEC['C'].append(np.asarray(predC, dtype=np.float32))
        per_line.setdefault(line, {'A': [], 'B': [], 'C': []})
        for tag, pred, store in [('A', predA, rA), ('B', predB, rB), ('C', predC, rC)]:
            store['all'].append(r2(real_mean, pred))
            store['degs'].append(r2(real_mean[degs], pred[degs]))
            store['pearson_all'].append(float(pearsonr(real_mean, pred)[0]))
            store['pearson_degs'].append(float(pearsonr(real_mean[degs], pred[degs])[0]))
            per_line[line][tag].append(r2(real_mean, pred))

    return rA, rB, rC, per_line


def m_(v): return float(np.mean(v)) if v else float('nan')

print("="*70)
