def _summ(v):
    a = np.asarray(v, dtype=float)
    if a.size == 0:
        return {'n': 0}
    return {'n': int(a.size), 'mean': float(a.mean()), 'median': float(np.median(a)),
            'sd': float(a.std(ddof=1)) if a.size > 1 else None,
            'n_negative': int((a < 0).sum()), 'min': float(a.min()), 'max': float(a.max())}
